arguments.keystrokes:
cat > /app/hierarchical_model.stan <<'EOF'
data {
  int<lower=1> N;
  array[N] int<lower=0> y;
  array[N] int<lower=0> n;
}
parameters {
  real<lower=0> alpha;
  real<lower=0> beta;
  vector<lower=0, upper=1>[N] theta;
}
model {
  // Prior proportional to (alpha + beta)^(-5/2).
  target += -2.5 * log(alpha + beta);
  theta ~ beta(alpha, beta);
  y ~ binomial(n, theta);
}
EOF
cat > /app/analysis.R <<'EOF'
options(mc.cores = parallel::detectCores())
options(java.parameters = "-Xmx2g")

if (!requireNamespace("rstan", quietly = TRUE) ||
    as.character(utils::packageVersion("rstan")) != "2.32.7") {
  repos <- c(
    stan = "https://mc-stan.org/r-packages/",
    CRAN = "https://cloud.r-project.org"
  )
  if (requireNamespace("rstan", quietly = TRUE)) {
    remove.packages("rstan")
  }
  install.packages("rstan", repos = repos, version = "2.32.7",
                   dependencies = TRUE)
}

library(rstan)
rstan_options(auto_write = TRUE)
rstan_options(threads_per_chain = 1)

dat <- read.csv("/app/data.csv", header = TRUE)
stopifnot(all(c("y", "n") %in% names(dat)))
stan_data <- list(
  N = nrow(dat),
  y = as.integer(dat$y),
  n = as.integer(dat$n)
)

fit <- sampling(
  stan_model("/app/hierarchical_model.stan"),
  data = stan_data,
  chains = 4,
  iter = 100000,
  seed = 1,
  refresh = 1000
)

posterior <- rstan::extract(fit, pars = c("alpha", "beta"), permuted = TRUE)
writeLines(sprintf("%.17g", mean(posterior$alpha)), "/app/posterior_alpha_mean.txt")
writeLines(sprintf("%.17g", mean(posterior$beta)), "/app/posterior_beta_mean.txt")
EOF
ls -l /app/hierarchical_model.stan /app/analysis.R
